/* Path: static/css/style.css */
/* Purpose: Stylesheet for ACM Problem-Solving Platform */
/* Layer: frontend */

/* General Reset */
body, h1, h2, h3, h4, h5, h6, p, ul, ol, li, div, span {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Body Styling */
body {
    font-family: 'Arial', sans-serif;
    font-size: 16px;
    background-color: #f4f4f9;
    color: #333;
    line-height: 1.6;
}

/* Navigation Bar */
.navbar {
    background-color: #2c3e50;
    color: #fff;
    padding: 1rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.navbar a {
    color: #fff;
    text-decoration: none;
    margin: 0 0.5rem;
}

.navbar a:hover {
    text-decoration: underline;
}

/* Main Content */
.main {
    padding: 2rem;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
}

/* Problem List */
.problem-list {
    list-style: none;
    padding: 0;
}

.problem-item {
    background-color: #fff;
    border: 1px solid #ddd;
    border-radius: 5px;
    margin-bottom: 1rem;
    padding: 1rem;
    transition: background-color 0.3s ease;
}

.problem-item:hover {
    background-color: #eaeaea;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 0.5rem 1rem;
    font-size: 1rem;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s ease;
}

.btn-primary {
    background-color: #3498db;
    color: #fff;
}

.btn-primary:hover {
    background-color: #2980b9;
}

.btn-secondary {
    background-color: #2ecc71;
    color: #fff;
}

.btn-secondary:hover {
    background-color: #27ae60;
}

/* Footer */
.footer {
    background-color: #2c3e50;
    color: #fff;
    text-align: center;
    padding: 1rem;
    margin-top: 2rem;
}

.footer a {
    color: #fff;
    text-decoration: none;
}

.footer a:hover {
    text-decoration: underline;
}

/* Leaderboard */
.leaderboard {
    margin: 2rem 0;
}

.leaderboard-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 1rem;
}

.leaderboard-table th,
.leaderboard-table td {
    padding: 0.5rem;
    text-align: left;
    border: 1px solid #ddd;
}

.leaderboard-table th {
    background-color: #3498db;
    color: #fff;
}

.leaderboard-table tr:nth-child(even) {
    background-color: #f9f9f9;
}

.leaderboard-table tr:hover {
    background-color: #eaeaea;
}

/* Responsive Design */
@media (max-width: 768px) {
    .navbar {
        flex-direction: column;
        align-items: flex-start;
    }

    .container {
        padding: 1rem;
    }

    .leaderboard-table {
        font-size: 0.9rem;
    }
}

// static/js/app.js

// Frontend JavaScript for ACM Problem-Solving Platform

// DOM Elements
const problemList = document.getElementById('problem-list');
const submitButton = document.getElementById('submit-button');
const codeInput = document.getElementById('code-input');
const resultDisplay = document.getElementById('result-display');
const leaderboard = document.getElementById('leaderboard');
const userProfile = document.getElementById('user-profile');

// Utility Functions
function fetchProblems() {
    fetch('/api/problems')
        .then(response => response.json())
        .then(data => renderProblemList(data))
        .catch(error => console.error('Error fetching problems:', error));
}

function renderProblemList(problems) {
    problemList.innerHTML = problems.map(problem => `
        <li class="problem-item" data-id="${problem.id}">
            ${problem.title}
        </li>
    `).join('');
}

function submitSolution(problemId, code) {
    fetch(`/api/problems/${problemId}/submit`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({ code: code }),
    })
    .then(response => response.json())
    .then(data => displayResult(data))
    .catch(error => console.error('Error submitting solution:', error));
}

function displayResult(result) {
    if (result.success) {
        resultDisplay.textContent = 'Success! Your solution is correct.';
        resultDisplay.classList.add('success');
    } else {
        resultDisplay.textContent = `Error: ${result.error}`;
        resultDisplay.classList.add('error');
    }
}

function fetchLeaderboard() {
    fetch('/api/leaderboard')
        .then(response => response.json())
        .then(data => renderLeaderboard(data))
        .catch(error => console.error('Error fetching leaderboard:', error));
}

function renderLeaderboard(data) {
    leaderboard.innerHTML = data.map(entry => `
        <li>
            ${entry.username} - ${entry.score} points
        </li>
    `).join('');
}

function fetchUserProfile(userId) {
    fetch(`/api/users/${userId}`)
        .then(response => response.json())
        .then(data => renderUserProfile(data))
        .catch(error => console.error('Error fetching user profile:', error));
}

function renderUserProfile(user) {
    userProfile.innerHTML = `
        <h2>${user.username}</h2>
        <p>${user.bio}</p>
        <p>Score: ${user.score}</p>
    `;
}

// Event Listeners
problemList.addEventListener('click', event => {
    const problemItem = event.target.closest('.problem-item');
    if (problemItem) {
        const problemId = problemItem.getAttribute('data-id');
        const code = codeInput.value;
        submitSolution(problemId, code);
    }
});

submitButton.addEventListener('click', () => {
    const selectedProblem = document.querySelector('.problem-item.selected');
    if (selectedProblem) {
        const problemId = selectedProblem.getAttribute('data-id');
        const code = codeInput.value;
        submitSolution(problemId, code);
    }
});

// Initialize Page
fetchProblems();
fetchLeaderboard();

from app import create_app

def main():
    app = create_app()
    app.run(host='0.0.0.0', port=5000)

if __name__ == "__main__":
    main()

